import sys

def prefixSuffixString(s1, s2):
    count = 0
    for w in s2:
        for v in s1:
            if v.startswith(w) or v.endswith(w):
                count += 1
                break
    return count

input = sys.stdin.read().strip().split()
s1 = input[:len(input)//2]
s2 = input[len(input)//2:]
print(prefixSuffixString(s1, s2))
